P = [
 dict(pmid='43017499', doi='10.1016/j.ssmph.2026.101984', journal='SSM Popul Health', title='Air pollution, public service provision, and perinatal health in China.', short='China 31-province panel 2003-2022 PM2.5 perinatal mortality public service digital information moderation threshold', design='Ecological panel', pm='Province-level PM2.5 (source not stated in abstract)', geo='China', endpoint='Perinatal health (inverse perinatal mortality rate)', tier='C', basis='Not stated', affil='Zhejiang University, China; The Chinese University of Hong Kong, China', n='Balanced provincial panel (31 provinces, 2003-2022) with two-way fixed effects, interaction and panel-threshold models. Higher PM2.5 was associated with poorer perinatal health; online information resources gave the most consistent attenuation, education investment, internet infrastructure and online applications showed regime differences, healthcare spending only suggestive attenuation and environmental-protection spending none. No effect sizes or exposure source are reported in the abstract. Province-year aggregates cannot address within-province exposure contrast, and moderation by spending categories that co-trend with income and time is open to residual confounding despite fixed effects. Relevance: indirect - ecological evidence that information access modifies PM-perinatal associations; no measurement content.', sub=corpus.REPR),
 dict(pmid='43017284', doi='10.1155/crp/9938043', journal='Cardiol Res Pract', title='Short-Term Interactive Effects of Temperature and Air Pollution on Cardiovascular Visits: A Machine-Learning Study in Hohhot, China.', short='Hohhot 508077 CVD visits 2016-2024 temperature x six pollutants polynomial ridge quasi-Poisson random forest', design='Time series', pm='Daily PM2.5, PM10, SO2, NO2, CO, O3 (monitoring source not stated)', geo='China (Inner Mongolia)', endpoint='Daily cardiovascular hospital visits', tier='B', basis='Not stated', affil='Inner Mongolia Medical University, China; Inner Mongolia Medical University, China', n='508,077 cardiovascular visits to tertiary hospitals in Hohhot (2016-2024) linked to daily temperature and six pollutants; polynomial ridge regression for interactions, quasi-Poisson for lags, random forest for prediction (cross-validated R2 0.741). High temperature amplified PM2.5 risk: cumulative change 30.96% (30.86-31.05%) at lag 0-7, increment not stated. Cold amplified PM10, NO2, CO and O3. A 0.2-point-wide interval on a 31% effect from a city time series is implausibly narrow and suggests overdispersion or autocorrelation was not propagated; visits rather than admissions mix severity. Relevance: indirect - interaction structure argues for temperature-stratified alert thresholds, which a sensor network could serve, but the headline estimate should not be quoted as precise.', sub=corpus.CVM),
 dict(pmid='43015926', doi='10.1186/s41021-026-00366-y', journal='Genes Environ', title='Invisible exposure, visible harm: air pollution and the global burden of cardiovascular disease.', short='Amity Kolkata narrative review air pollution global burden cardiovascular disease GBD 2021 mechanisms omics prevention', design='Narrative review', pm='PM2.5, PM10, ultrafine particles and gaseous co-pollutants (literature)', geo='Global', endpoint='Pollution-attributable cardiovascular disease', tier='C', basis='Review / no primary exposure', affil='Amity University Kolkata, India; Amity University Kolkata, India', n='Narrative review from a structured PubMed/Scopus/Web of Science search covering pollutant sources, GBD 2021 burden (air pollution the second leading risk factor, 8.1 million deaths; ambient plus household PM about 4.5 million cardiovascular deaths), cohort and multi-city evidence, mechanisms separated by human versus cell/animal support, phenotype-specific associations, susceptible groups, omics findings and prevention graded by evidence strength. No new data or pooled estimate; the selection process for a narrative review is not reproducible, and the burden figures are GBD outputs rather than independent estimates. Relevance: indirect - a usable summary of which mechanisms rest on human data; it does not address exposure measurement error, which is where distributed sensing would change the estimates it summarises.', sub=corpus.CVM),
 dict(pmid='43015867', doi='10.1186/s13690-026-02137-1', journal='Arch Public Health', title='Air pollution exposure during urban running in Frankfurt, Germany: a randomized crossover comparison of particulate matter levels on park, roadside, and residential routes across morning and early afternoon hours.', short='Frankfurt 60 runs randomized crossover road residential park morning afternoon mobile PM10 PM2.5 PM1', design='Randomized crossover measurement', pm='Mobile PM10, PM2.5 and PM1 during 2-km runs plus urban-background PM2.5/PM10', geo='Germany (Frankfurt)', endpoint='In-run PM concentration by route and time of day', tier='B', basis='Personal / wearable', affil='Goethe University Frankfurt, Germany; Goethe University Frankfurt, Germany', n='Sixty 2-km runs randomised across a major road, residential streets and an urban park (20 each), morning versus early afternoon (30 each), with mobile PM10/PM2.5/PM1 measurement and linear mixed models adjusted for meteorology. Lowest fine and submicron levels occurred on early-afternoon park runs; the park did not reduce, and in the morning raised, PM10. Humidity, pressure, wind and temperature were associated with in-run exposure. A run-level sensitivity analysis (n=60) lost the route and route-by-time effects, so the authors call the pattern preliminary; the instrument and its correction are not named in the abstract. Relevance: direct - a microenvironment contrast of the size a portable optical sensor would be asked to resolve, and an example of how few runs that takes to fail.', sub=corpus.EXPO),
]
